import React from "react";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskListProps{
    tasks: Task[];
    markTaskAsDone: (id: number) => void;
}

const TaskList: React.FC<TaskListProps> = ({ tasks, markTaskAsDone }) => {
    return(
        <div>
            <h2>Task List</h2>

            {tasks.length === 0 ? (
                <p>No available tasks!</p>
            ) : (
                <ul>
                    {tasks.map((task) => (
                        <li key={task.id}>
                            <strong>{task.text}</strong> - {task.priority} -{" "}
                            {task.doneFlag ? "Done" : "Pending"}

                            {!task.doneFlag && (
                                <button onClick={() => markTaskAsDone(task.id)}>Mark as Done</button>
                            )}
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default TaskList;
